package protocol

import (
	"crypto/rand"
	"encoding/hex"
	"fmt"
)

const opaqueIDBytes = 16

// SessionID is generated by trusted bootstrap and bound to one control channel.
type SessionID [opaqueIDBytes]byte

// ResourceID is generated by the owning broker. Native names and handles are
// never valid resource IDs.
type ResourceID [opaqueIDBytes]byte

func NewSessionID() (SessionID, error) {
	var id SessionID
	_, err := rand.Read(id[:])
	return id, err
}

func NewResourceID() (ResourceID, error) {
	var id ResourceID
	_, err := rand.Read(id[:])
	return id, err
}

func (id SessionID) Valid() bool  { return !allZero(id[:]) }
func (id ResourceID) Valid() bool { return !allZero(id[:]) }

func (id SessionID) String() string  { return hex.EncodeToString(id[:]) }
func (id ResourceID) String() string { return hex.EncodeToString(id[:]) }

func ParseSessionID(value string) (SessionID, error) {
	var id SessionID
	if err := decodeOpaqueID(value, id[:]); err != nil {
		return SessionID{}, fmt.Errorf("%w: session ID: %v", ErrInvalidContract, err)
	}
	return id, nil
}

func ParseResourceID(value string) (ResourceID, error) {
	var id ResourceID
	if err := decodeOpaqueID(value, id[:]); err != nil {
		return ResourceID{}, fmt.Errorf("%w: resource ID: %v", ErrInvalidContract, err)
	}
	return id, nil
}

func decodeOpaqueID(value string, out []byte) error {
	if len(value) != hex.EncodedLen(len(out)) {
		return fmt.Errorf("must contain %d hexadecimal characters", hex.EncodedLen(len(out)))
	}
	if _, err := hex.Decode(out, []byte(value)); err != nil {
		return err
	}
	if allZero(out) {
		return fmt.Errorf("must not be zero")
	}
	return nil
}

func allZero(value []byte) bool {
	var combined byte
	for _, item := range value {
		combined |= item
	}
	return combined == 0
}
